    if (!provided) out.push(lib.finding(ERR, manifest, `contract item "${item}" has no provider`));
    else if (/^missing\b/i.test(provided)) out.push(lib.finding(ERR, manifest, `contract item "${item}" is missing; raise a Decision Request before selecting this implementation`));
  }
}

function checkLeaks(artifacts, modules, registerBlock, out) {
  // Allowed: module facets and manifest, the maintainer map, the register's selection block and its accepted-decision log,
  // and project-owned product/build files (product inputs and package manifests legitimately name technologies).
  const reg = artifacts.get(REGISTER);
  const decisionLog = reg ? reg.text.slice(Math.max(0, reg.text.indexOf('## Accepted decisions'))) : '';
  for (const mod of modules) {
    const patterns = mod.names.map(n => ({ name: n, re: new RegExp(`(?<![A-Za-z0-9])${escapeRegex(n)}(?![A-Za-z0-9])`, 'i') }));
    for (const a of artifacts.values()) {
      if (mod.files.includes(a.rel) || a.rel.startsWith(`.claude/capabilities/${mod.id}/`) || a.rel === MAP || PROJECT_OWNED.includes(a.rel)) continue;
      const text = a.rel === REGISTER ? a.text.replace(registerBlock, '').replace(decisionLog, '') : a.text;
      const hit = patterns.find(p => p.re.test(text));
      if (hit) out.push(lib.finding(ERR, a.rel, `names the selected ${mod.slot} implementation ("${hit.name}") outside its module; refer to the slot/facet role`));
    }
  }

function checkMap(root, files, out) {
  if (!lib.exists(root, MAP)) {
    out.push(lib.finding(ERR, MAP, 'maintainer map is missing'));
    return;
  }
  const map = lib.readText(root, MAP);
  for (const rel of files) {
    if (rel === MAP) continue;
    if (!map.includes(`\`${rel}\``)) out.push(lib.finding(ERR, MAP, `artifact not listed: ${rel}`));
  }
  for (const m of map.matchAll(/`((?:\.claude\/|docs\/architecture\/)[^`\s<>*{}]+\.[a-z]+|CLAUDE\.md|SPECIFICATION\.md|CUSTOM_SETTINGS\.md|Directory\.(?:Build|Packages)\.props|\.editorconfig)`/g)) {
    if (!lib.exists(root, m[1])) out.push(lib.finding(ERR, MAP, `lists a missing artifact: ${m[1]}`));
  }
  for (const slot of Object.keys(SLOTS)) if (!new RegExp(`###\\s+${slot}\\b`).test(map)) out.push(lib.finding(ERR, MAP, `capability view lacks slot "${slot}"`));
}

function checkVocabulary(artifacts, out) {
  for (const a of artifacts.values()) {
    if (!a.header || !['OP', 'DEC', 'STD'].includes(a.header.kind)) continue;
    if (/\bnormally\b/i.test(a.body)) out.push(lib.finding(WARN, a.rel, 'ambiguous "normally" in normative text; use must/default/prefer'));
  }
}

function alwaysLoadedTokens(artifacts, skills, imports) {
  let chars = 0;
  for (const rel of ['CLAUDE.md', ...imports]) if (artifacts.get(rel)) chars += artifacts.get(rel).text.length;
  for (const [name, a] of skills) {
    if (frontmatterValue(a.frontmatter, 'disable-model-invocation') === 'true') continue;
    chars += name.length + (frontmatterValue(a.frontmatter, 'description') || '').length + 4;
  }
  for (const a of artifacts.values()) {
    if (a.rel.startsWith('.claude/agents/')) chars += (frontmatterValue(a.frontmatter, 'description') || '').length;
  }
  return Math.round(chars / 4);
}

/**
 * Active repository/worktree root for a working directory (hook input `cwd`, or process.cwd() for commands):
 * the Git top level containing it (a linked worktree resolves to that worktree, also when it sits inside the
 * main checkout); a nested independent repository resolves to the enclosing project (nearest ancestor with
 * CLAUDE.md and .claude); outside Git, that project root or the directory itself.
 */
function activeRoot(cwd) {
  const start = realpath(nearestExisting(cwd || process.cwd()));
  const top = git(start, ['rev-parse', '--show-toplevel']);
  const gitTop = top && top.status === 0 && top.stdout.trim() ? realpath(top.stdout.trim()) : null;
  if (gitTop && fs.existsSync(path.join(gitTop, '.claude'))) return gitTop;
  let project = null;
  for (let d = start; ; d = path.dirname(d)) {
    if (isProjectRoot(d)) {
      project = d;
      break;
    }
    if (path.dirname(d) === d) break;
  }
  if (gitTop && project && gitCommonDir(gitTop) === gitCommonDir(project)) return gitTop; // worktree of the same repository
  return project || gitTop || start;
}

/** Root inspected by a command-line checker: the repository containing the current directory, else the script's own. */
function commandRoot(scriptDir) {
  const root = activeRoot(process.cwd());
  return fs.existsSync(path.join(root, '.claude')) ? root : rootFrom(scriptDir, 2);
}

function stop(input) {
  if (input.stop_hook_active) return 0; // never re-block a continuation triggered by this hook
  const cochange = require('../scripts/check-cochange.cjs');
  const result = cochange.run(lib.activeRoot(workingDirectory(input)), 'hook');
  if (!result.applicable) {
    process.stdout.write(`${JSON.stringify({ systemMessage: 'Co-change reminders inactive: the project is not a Git work tree.' })}\n`);
    return 0;
  }
  if (!result.reminders.length) return 0;
  process.stderr.write(
    `Co-change reminders (reported once per content state):\n${cochange.format(result.reminders)}\n` +
    'Address each item or state why it does not apply, then finish.\n');
  return 2;
}

/** Framework-neutral reminder: backend production code changed without any backend test change. */
function testReminder(changes) {
  const isBackendCs = p => p.startsWith('backend/') && p.endsWith('.cs');
  const isTest = p => /^backend\/[^/]*Tests?\//.test(p);
  const production = changes.filter(c => isBackendCs(c.path) && !isTest(c.path) && !c.status.includes('D'));
  if (!production.length || changes.some(c => isTest(c.path))) return [];
  return [{
    id: 'tests',
    message: `backend production code changed (${production.length} file(s)) with no backend test change; confirm coverage and probe preservation`,
    owner: 'verify workflow (step 4), development-workflow (bug fixes)',
    paths: production.map(c => c.path),
  }];
}

/** Content identity of one reminder: its id plus the current bytes of every path that triggered it. */
function fingerprint(root, reminder) {
  const hash = crypto.createHash('sha256').update(reminder.id);
  for (const rel of [...(reminder.paths || [])].sort()) {
    hash.update(`\0${rel}\0`);
    try {
      hash.update(fs.readFileSync(path.join(root, rel)));
    } catch {
      hash.update('\0missing');
    }
  }
  return hash.digest('hex').slice(0, 24);
}

function stateFile(root) {
  const gitDir = git(root, ['rev-parse', '--absolute-git-dir']);
  if (gitDir.status !== 0) throw new Error(`git rev-parse failed: ${gitDir.stderr.trim()}`);
  return path.join(gitDir.stdout.trim(), STATE_FILE);
}

/** Reminders whose content identity was not reported before; records them (bounded, per worktree). */
function unreported(root, reminders) {
  const file = stateFile(root);
  let state = { fingerprints: [] };
  try {
    const loaded = JSON.parse(fs.readFileSync(file, 'utf8'));
    if (Array.isArray(loaded.fingerprints)) state = loaded;
  } catch {
    state = { fingerprints: [] };
  }
  const known = new Set(state.fingerprints);
